import fs from'fs';
import{execSync}from'child_process';
var stylezero_style_version=1;
var allow_stylezero_execution=true;
const stylezero_bin=process.platform==='win32'?'%LocalAppData%\\Programs\\StyleZero\\stylezero':'~/.local/opt/stylezero/stylezero';
const root_dir=process.cwd().replaceAll('\\','/')+'/';
const src_dir=root_dir+'src/';
let extensions=[];
let out_directory;
try{
	const sz_config=JSON.parse(fs.readFileSync(root_dir+'stylezero.json','utf-8'));
	extensions=sz_config.extensions;
	out_directory=root_dir+sz_config.out_directory+'/';
}
catch(err){
	setTimeout(()=>console.warn('[stylezero] Failed to read stylezero.json'),1000);
}
export default function stylezero(){
	return{
		name:'stylezero',
		enforce:'pre',
		transform(code,path){
			if(!path.startsWith(src_dir))
				return;
			if(!extensions.some(ext=>path.endsWith(ext)))
				return;
			if(allow_stylezero_execution){
				allow_stylezero_execution=false;
				setTimeout(()=>allow_stylezero_execution=true,1000);
				execSync(stylezero_bin,{encoding:'utf-8'});
			}
			var compiled_path=path.replace(src_dir,out_directory);
			return fs.readFileSync(compiled_path,'utf-8');
		},
		closeBundle(){
			fs.rmSync('dist/cache',{recursive:true,force:true});
		}
	}
};
